7	'use strict';
8	
9	// Every route the page calls, method and path. A host test reads this
10	// table and checks that each one is served.
11	const API = {
12	  info: 'GET /api/v1/info',
13	  pair: 'POST /api/v1/pair',
14	  me: 'GET /api/v1/me',
15	  projects: 'GET /api/v1/projects',
16	  sessions: 'GET /api/v1/projects/{id}/sessions',
17	  waiting: 'GET /api/v1/waiting',
18	  lastResponse: 'GET /api/v1/sessions/{id}/last-response',
19	  screen: 'GET /api/v1/sessions/{id}/screen',
20	  send: 'POST /api/v1/sessions/{id}/send',
21	  events: 'GET /api/v1/events',
22	};
23	
24	const STORE_KEY = 'switchboard-host';
25	const POLL_FAST_MS = 3000;
26	const POLL_SLOW_MS = 20000;
27	const SOCKET_RETRY_MS = 5000;
