32	/** The invite in a URL fragment, `#code=…&key=…&id=…`, or null. */
33	function parseFragment(hash) {
34	  const text = (hash || '').replace(/^#/, '');
35	  const fields = {};
36	  for (const pair of text.split('&')) {
37	    const at = pair.indexOf('=');
38	    if (at <= 0) continue;
39	    try {
40	      fields[pair.slice(0, at)] = decodeURIComponent(pair.slice(at + 1));
41	    } catch (_) {
